(()=>{'use strict';const banner=document.querySelector('.fixed.inset-x-0.top-0 p');const date=new Intl.DateTimeFormat('es-MX',{timeZone:'America/Mexico_City',day:'numeric',month:'long'});const duration=86400000,key='lina-mx-clock-cycle-v1';let end=Date.now()+duration;try{const saved=Number(localStorage.getItem(key));if(Number.isFinite(saved)&&saved>0)end=saved;}catch{}function update(){const now=Date.now();if(end<=now)end+=duration*(Math.floor((now-end)/duration)+1);try{localStorage.setItem(key,String(end));}catch{}if(banner)banner.textContent='🎄 CONDICIÓN ESPECIAL DE NAVIDAD · '+date.format(new Date(now));const remaining=Math.max(0,Math.ceil((end-now)/1000));const values={hours:Math.floor(remaining/3600),minutes:Math.floor(remaining%3600/60),seconds:remaining%60};for(const [name,value] of Object.entries(values))document.querySelectorAll('[data-day-'+name+']').forEach(e=>e.textContent=String(value).padStart(2,'0'));}update();setInterval(update,1000);})();
